"""World War II Lesson 3 deck builder. Image led deck: Liberty ship launch title, Vultee drill photograph, Rosie poster, Richmond shipyard worker, bond poster, ration book."""
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
LESSON_DIR = os.path.dirname(HERE)
UNIT_DIR = os.path.dirname(LESSON_DIR)
sys.path.insert(0, UNIT_DIR)
import deck_common as dc
from deck_common import (slide, rect, text, notes, kicker, rule, frags,
                         divider_photo, content_photo, content_text, stat, divider_text,
                         NAVY, CREAM, RUST, RUST_LT, POWDER, INK, MUTED, W, H)
from pptx.enum.text import PP_ALIGN
from pptx.util import Inches

dc.IMG = os.path.join(HERE, 'img')
OUT = os.path.join(LESSON_DIR, 'lesson-03-slides.pptx')

spec = open(os.path.join(UNIT_DIR, 'build-scripts', 'unit-spec.md')).read()
sec = spec.split('### Lesson 3')[1].split('### Lesson 4')[0]
TERMS = []
for line in sec.splitlines():
    line = line.strip()
    if line.startswith('- '):
        t, d = line[2:].split(': ', 1)
        TERMS.append((t.strip(), d.strip()))
assert len(TERMS) == 7, TERMS
TD = dict(TERMS)

def vocab(title, terms, note, kick='The vocabulary'):
    s = slide(CREAM)
    kicker(s, kick, color=RUST)
    text(s, 0.9, 0.95, 11.5, 1.0, title, size=30, color=NAVY, font='Georgia')
    yy = 2.1
    for term, dfn in terms:
        text(s, 0.9, yy, 4.1, 0.9, term, size=24, color=NAVY, font='Georgia')
        text(s, 5.15, yy + 0.06, 7.3, 1.1, dfn, size=18, color=MUTED, leading=1.2)
        yy += 1.52
    notes(s, note)
    return s

SHORT = {
 'mobilization': 'preparing the armed forces, industry, and economy for war',
 'Selective Training and Service Act': 'the 1940 law creating the first peacetime draft',
 'War Production Board': 'the 1942 agency directing conversion and allocating scarce materials',
 'war bonds': 'government bonds sold to the public to raise war money, repaid with interest',
 'rationing': 'limits on how much of a scarce good each person may buy, by coupons or stamps',
 'Office of Price Administration': 'the agency that set price ceilings and ran rationing',
 'Rosie the Riveter': 'the popular name and image for women who took factory and shipyard jobs',
}

# 1 TITLE
s = slide(NAVY)
s.shapes.add_picture(os.path.join(dc.IMG, 'title-169.jpg'), 0, 0, Inches(13.333), Inches(7.5))
rect(s, 0, 5.05, W, 2.45, NAVY)
rect(s, 0, 5.05, W, 0.045, RUST)
text(s, 0.9, 5.32, 11.5, 0.4, 'WORLD WAR II · LESSON 3', size=14, color=RUST_LT, font='Arial', bold=True)
text(s, 0.9, 5.68, 11.9, 1.1, 'Mobilizing the Home Front', size=30, color=CREAM, font='Georgia')
text(s, 0.9, 6.62, 11.5, 0.5, 'Twelve million in uniform, 300,000 aircraft, and a ration book in every kitchen. How a peacetime economy became an arsenal.', size=17, color=POWDER)
notes(s, "Open with the photograph and the scale it stands for. These are Liberty era cargo ships launching at South Portland, Maine in August 1942, eight months after Pearl Harbor, from yards that had to be built or converted while the war was already running. Lesson 2 ended with an arsenal that existed mostly as a promise and a set of factory orders. This lesson keeps the promise and prices it. Students will follow three conversions at once: a small peacetime army into a force of more than twelve million, a consumer economy into the largest war production system in the world, and a population of the unemployed into drafted soldiers, riveters, welders, and migrants. Hold the closing fact in reserve from the start. The spending and direction in this lesson, not the New Deal programs of the last unit, is what finally ended the Depression, and the lesson ends by proving that claim with the unemployment figure of 1944.")
# 2 QUESTION
s = slide(NAVY)
kicker(s, 'The question for today')
text(s, 0.9, 1.9, 11.5, 3.4, [[('How did the United States turn a peacetime economy into the arsenal the war required, and who did the work?', {})]], size=42, color=CREAM, font='Georgia', leading=1.25)
rule(s, 0.92, 5.6)
text(s, 0.92, 5.85, 11.5, 0.9, [[('Unit question: ', {'color': RUST_LT, 'italic': True}), ('How did the Second World War transform the United States, and how far did the country live up to the democracy it claimed to defend?', {'italic': True})]], size=17, color=POWDER, font='Georgia', leading=1.2)
notes(s, "Read the lesson question aloud and separate its two halves, because the exit ticket and the writing task grade them separately. The first half asks for a mechanism: how was the conversion done, by what laws, agencies, controls, and payments. An answer that says the country worked hard has named an attitude, not a mechanism, and should not earn full credit anywhere in this lesson. The second half asks who did the work, and the honest answer is wider than the peacetime workforce of 1941. It includes drafted men, six million women entering paid work, and Black, Mexican American, and Native American migrants who moved across the country to the yards and plants. Connect the question to the unit question beneath it. The transformation half of the unit question is built here: a directed economy, a moved population, and a labor force redrawn in four years.")
# 3 MAP
s = slide(NAVY)
kicker(s, 'The lesson in one slide')
text(s, 0.9, 1.28, 11.5, 1.0, 'An army, a production miracle, and the end of the Depression', size=42, color=CREAM, font='Georgia')
rule(s, 0.92, 2.36)
rows = [('A', 'An Army of Twelve Million', 'From under 200,000 soldiers to twelve million in uniform'),
        ('B', 'The Production Miracle', 'Cars to tanks, Liberty ships in weeks, 300,000 aircraft'),
        ('C', 'The Agencies That Ran It', 'The War Production Board and the price and ration office'),
        ('D', 'Paying for the War', 'War bonds and a new mass income tax'),
        ('E', 'The Women Who Built the Arsenal', 'Six million women enter paid war work'),
        ('F', 'The Migration to War Work', 'A second Great Migration to the war industry cities'),
        ('G', 'The Depression Ends', 'Unemployment at about 1.2 percent in 1944')]
